mapper.select:
select * from Alram
whoUserCode = #{code}
order by alramCreate DESC limit 0,20

select * from Alram

    whoUserCode = #{userCode}

        AND alramTitle = #{title}


order by alramCreate DESC
limit #{cri.skip},#{cri.amount}

select count(*) from Alram

    whoUserCode = #{userCode}

        AND alramTitle = #{title}


order by alramCreate DESC

mapper.insert:
insert into alram(
    alramTitle,
    alramTitleCode,
    whoUserCode,
    userCode
)
value(
    #{alramTitle},
    #{alramTitleCode},
    #{whoUserCode},
    #{userCode}
);

mapper.update:
update alram
set alramState = true
where alramCode = #{code}

mapper.select:
select JGnoticeTitle as alramTitle,jgnoticeimg as alramImg from jgnotice notice
join jgnoticeImg img ON notice.JGNoticeCode = img.JGNoticeCode
where notice.JGNoticeCode = #{code}
limit 1;

select JGnoticeTitle as alramTitle from jgnoticesubcribe sub
join jgnotice notice ON sub.JGNoticeCode = notice.JGNoticeCode
where sub.JGNoticeCode = #{code}

select notificationManagementTitle as alramTitle from alram as ram
join notificationManagement as noti ON ram.alramTitleCode = noti.notificationManagementCode
where ram.alramCode = #{code};
